package cn.workbench;

import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import static cn.workbench.Records.map;

@Service public class RolePermissions {
 static final List<String> ROLES=List.of("GROUP_LEADER","DIVISION_LEADER","COMPANY_LEADER","DEPT_HEAD","EMPLOYEE","ADMIN");
 static final Map<String,String> CATALOG=Map.ofEntries(Map.entry("TASK_VIEW","查看任务"),Map.entry("TASK_CREATE","创建主任务"),Map.entry("TASK_UPDATE","办理任务和子任务"),Map.entry("ATTACHMENTS","附件上传与下载"),Map.entry("COLLABORATION","协同确认"),Map.entry("REPORTS","统计与导出"),Map.entry("KPI","部门考核"),Map.entry("ORGANIZATION","岗位与交接"),Map.entry("NOTIFICATIONS","通知中心"),Map.entry("USER_ADMIN","用户与岗位管理"),Map.entry("ORG_ADMIN","公司与部门管理"),Map.entry("RULE_ADMIN","职能标签与匹配规则"),Map.entry("CHANNEL_ADMIN","通知渠道管理"),Map.entry("AUDIT","操作日志"));
 final Records records;final JdbcTemplate jdbc;final Writes writes;
 public RolePermissions(Records records,JdbcTemplate jdbc,Writes writes){this.records=records;this.jdbc=jdbc;this.writes=writes;}
 String kind(String role){return "ROLE_PERMISSIONS_"+role;}
 Map<String,Object> current(String role){var rows=records.list(kind(role),0,null);if(rows.size()>1)throw new IllegalStateException("Duplicate role permission configuration");return rows.isEmpty()?null:rows.getFirst();}
 Set<String> disabled(String role){if(!ROLES.contains(role))return Set.of();var row=current(role);if(row==null)return Set.of();Object value=row.get("disabled");if(!(value instanceof List<?> list))throw new IllegalStateException("Invalid role permission configuration");Set<String> result=new HashSet<>();for(var v:list){if(!(v instanceof String s)||!CATALOG.containsKey(s))throw new IllegalStateException("Invalid role permission");result.add(s);}return result;}
 static Set<String> supported(String role){var base=new HashSet<>(Set.of("TASK_VIEW","TASK_UPDATE","ATTACHMENTS","COLLABORATION","ORGANIZATION","NOTIFICATIONS"));if(Set.of("GROUP_LEADER","DIVISION_LEADER","COMPANY_LEADER").contains(role))base.addAll(Set.of("TASK_CREATE","REPORTS","KPI","AUDIT"));if(role.equals("DEPT_HEAD"))base.addAll(Set.of("REPORTS","KPI"));if(role.equals("EMPLOYEE"))base.remove("COLLABORATION");if(role.equals("ADMIN"))return Set.of("TASK_VIEW","KPI","ORGANIZATION","NOTIFICATIONS","USER_ADMIN","ORG_ADMIN","RULE_ADMIN","CHANNEL_ADMIN","AUDIT");return base;}
 List<String> allowed(String role,boolean globalAdmin){var denied=globalAdmin?Set.<String>of():disabled(role);return CATALOG.keySet().stream().filter(p->(globalAdmin||supported(role).contains(p))&&!denied.contains(p)&&!(denied.contains("TASK_VIEW")&&requiresTaskView(p))).sorted().toList();}
 static boolean requiresTaskView(String permission){return Set.of("TASK_CREATE","TASK_UPDATE","ATTACHMENTS","COLLABORATION","REPORTS","KPI","NOTIFICATIONS","ORGANIZATION").contains(permission);}
 Map<String,Object> read(String role){var row=current(role);return map("role",role,"version",row==null?-1:row.get("version"),"disabled",disabled(role).stream().sorted().toList(),"supported",supported(role).stream().sorted().toList(),"effective",allowed(role,false));}
 public List<Map<String,Object>> list(){return ROLES.stream().map(this::read).toList();}
 public Map<String,Object> save(Policy.Actor actor,String role,Map<String,Object> input){if(!actor.globalAdmin()||!ROLES.contains(role))throw ApiException.denied();if(!(input.get("disabled") instanceof List<?> list))throw TaskService.invalid("请选择有效的权限");Set<String> desired=new TreeSet<>();for(Object value:list)if(!(value instanceof String s)||!CATALOG.containsKey(s)||!desired.add(s))throw TaskService.invalid("权限无效或重复");var lock=jdbc.queryForList("SELECT id FROM company ORDER BY id LIMIT 1 FOR UPDATE");if(lock.isEmpty())throw new ApiException(409,"COMPANY_REQUIRED","请先创建公司");var previous=disabled(role).stream().sorted().toList();var row=current(role);int version=TaskService.integer(input,"version");if(row==null){if(version!=-1)throw ApiException.conflict();row=records.create(kind(role),0,null,null,actor.uid(),"ACTIVE",map("role",role,"disabled",desired.stream().toList()));}else{if(version!=TaskService.integer(row,"version"))throw ApiException.conflict();row=records.lock(TaskService.number(row,"id"));row.put("disabled",desired.stream().toList());records.save(row);}var change=records.create("ROLE_PERMISSION_CHANGE",0,null,null,actor.uid(),"RECORDED",map("role",role,"before",previous,"after",desired.stream().toList()));writes.audit(actor,"ROLE_PERMISSION_UPDATE",TaskService.number(change,"id"));jdbc.update("UPDATE app_user SET session_version=session_version+1 WHERE id IN (SELECT user_id FROM user_scope WHERE role=?"+(role.equals("ADMIN")?" AND company_id IS NOT NULL":"")+")",role);return read(role);}
 static String path(HttpServletRequest q){String uri=q.getRequestURI(),context=q.getContextPath();return context.isEmpty()?uri:uri.substring(context.length());}
 static String required(HttpServletRequest q){String p=path(q),m=q.getMethod();if(!p.startsWith("/api/v1/"))return null;boolean get=Set.of("GET","HEAD").contains(m);if(p.matches("/api/v1/collections(/[0-9]+(/(draft|submit|export))?)?"))return p.endsWith("/export")?"REPORTS":get?"TASK_VIEW":p.equals("/api/v1/collections")?"TASK_CREATE":"TASK_UPDATE";if(p.matches("/api/v1/admin/users(/.*)?"))return "USER_ADMIN";if(p.matches("/api/v1/admin/(companies|departments)(/.*)?"))return "ORG_ADMIN";if(p.matches("/api/v1/admin/(tags|rules)(/.*)?"))return "RULE_ADMIN";if(p.matches("/api/v1/admin/notification-channels(/.*)?"))return "CHANNEL_ADMIN";if(p.equals("/api/v1/audit")||p.equals("/api/v1/audit/export"))return "AUDIT";if(p.startsWith("/api/v1/attachments"))return "ATTACHMENTS";if(p.startsWith("/api/v1/collaborations"))return "COLLABORATION";if(p.startsWith("/api/v1/notifications"))return "NOTIFICATIONS";if(p.startsWith("/api/v1/kpi/")||p.startsWith("/api/v1/admin/kpi/")||p.matches("/api/v1/tasks/[0-9]+/classification"))return "KPI";if(p.startsWith("/api/v1/stats/")&&!p.equals("/api/v1/stats/overview"))return "REPORTS";if(p.equals("/api/v1/stats/overview"))return "TASK_VIEW";if(p.matches("/api/v1/organization/(appointments|delegations|handover-tasks|handovers)(/.*)?"))return "ORGANIZATION";if(p.startsWith("/api/v1/matching/")||p.equals("/api/v1/tasks/match"))return "TASK_CREATE";if(p.equals("/api/v1/tasks")&&!get)return "TASK_CREATE";if(p.startsWith("/api/v1/tasks")||p.startsWith("/api/v1/sub-tasks")||p.startsWith("/api/v1/work-items")||p.startsWith("/api/v1/deadline-requests"))return get?"TASK_VIEW":"TASK_UPDATE";if(p.startsWith("/api/v1/auth/")||p.equals("/api/v1/admin/role-permissions")||p.startsWith("/api/v1/admin/role-permissions/")||get&&Set.of("/api/v1/organization/departments","/api/v1/organization/collaboration-departments","/api/v1/organization/users").contains(p))return null;return "UNMAPPED";}
}
